-- ══════════════════════════════════════════════
--  appearance.lua — window look: shape, translucency, blur, shadow
--
--  Shape/opacity/blur numbers come from blend.lua (shared with Quickshell, so a
--  window and a panel round and fade the same). Colours come from palette.lua
--  (generated by scripts/wal-reload.sh from the current wallpaper). Requires
--  both — hyprland.lua loads them first.
-- ══════════════════════════════════════════════

local blend = require("blend")

hl.config({
    general = {
        gaps_in     = blend.gaps_in,
        gaps_out    = blend.gaps_out,
        border_size = blend.border_size,
        col = {
            active_border   = border_active,    -- palette.lua (blend.border_active_wal)
            inactive_border = border_inactive,  -- palette.lua (blend.border_inactive_wal)
        },
        resize_on_border = false,
        -- On for games. A window only actually tears if it ASKS to (the tearing
        -- protocol) AND carries the `immediate` rule — rules.lua grants that to
        -- fullscreen windows, so a normal desktop window is unaffected.
        allow_tearing    = true,
        layout           = "dwindle",
    },

    decoration = {
        rounding         = blend.rounding,
        rounding_power   = blend.rounding_power,
        active_opacity   = blend.active_opacity,
        inactive_opacity = blend.inactive_opacity,

        shadow = {
            enabled      = true,
            range        = 4,
            render_power = 3,
            color        = shadow_color,        -- palette.lua
        },

        blur = {
            enabled  = true,
            size     = blend.blur_size,
            passes   = blend.blur_passes,
            contrast = 1,
            vibrancy = blend.blur_vibrancy,
        },

        -- Springy window deformation while moving/resizing (Hyprland 0.57+; an
        -- older Hyprland rejects the key). Toggled from the shell's Tuning page —
        -- keep it the third `enabled` in this file (hypr-config.py counts them).
        wobble = {
            enabled   = false,
            mesh      = 12,
            stiffness = 200,
            damping   = 12,
            mass      = 1,
        },
    },
})
